```python
import csv
import json
import numpy as np
import stan

with open("/app/gp_ard_regression.stan") as f:
    STAN_CODE = f.read()

def read_matrix(path):
    with open(path) as f:
        r = csv.reader(f)
        next(r)
        return np.array([[float(x) for x in row] for row in r if row])

def read_vector(path, col=0):
    with open(path) as f:
        r = csv.reader(f)
        next(r)
        return np.array([float(row[col]) for row in r if row])

def main():
    train_X = read_matrix("/app/train_X.csv")
    test_X = read_matrix("/app/test_X.csv")
    y = read_vector("/app/train_y.csv")
    with open("/app/meta_public.json") as f:
        meta = json.load(f)
    P = int(meta["P"])
    jitter = float(meta["jitter"])
    N = train_X.shape[0]
    D = train_X.shape[1]
    N_new = test_X.shape[0]
    H = np.column_stack([np.ones(N), train_X[:, 0], train_X[:, 1]])
    H_new = np.column_stack([np.ones(N_new), test_X[:, 0], test_X[:, 1]])
    data = dict(N=N, D=D, X=train_X, P=P, H=H, y=y, jitter=jitter,
                N_new=N_new, X_new=test_X, H_new=H_new)
    print("N", N, "D", D, "N_new", N_new, "P", P, "jitter", jitter)
    model = stan.build(STAN_CODE, data=data, random_seed=1)
    fit = model.sample(num_chains=4, num_samples=1000, num_warmup=1000,
                       num_thin=2, save_warmup=False, delta=0.93, max_depth=14,
                       gamma=0.05, kappa=0.75, t0=10, init_buffer=100,
                       term_buffer=50, window=25, init_radius=0.1, refresh=200)
    alpha_est = float(np.asarray(fit["alpha"]).mean())
    sigma_est = float(np.asarray(fit["sigma"]).mean())
    rho_est = np.asarray(fit["rho"]).mean(axis=1)
    beta_est = np.asarray(fit["beta"]).mean(axis=1)
    print("alpha", alpha_est)
    print("sigma", sigma_est)
    print("rho", rho_est)
    print("beta", beta_est)
    np.savetxt("/app/alpha_est.csv", np.array([alpha_est]))
    np.savetxt("/app/sigma_est.csv", np.array([sigma_est]))
    np.savetxt("/app/rho_est.csv", rho_est)
    np.savetxt("/app/beta_est.csv", beta_est)
    print("DONE")

if __name__ == "__main__":
    main()
```

